command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-name-index --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "86d08481ec77fb7478abec29ab4df718cb7991ce") { throw "main moved" }
if ((git rev-parse origin/work/large-folder-name-index).Trim() -ne "504646353dda2725d89052fdd56926b6de2d91b7") { throw "candidate branch moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-name-index origin/work/large-folder-name-index
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "504646353dda2725d89052fdd56926b6de2d91b7") { throw "candidate mismatch" }
python -X utf8 -m py_compile tests\winui\test_remote_windows_task_contract.py tests\winui\test_large_owned_folder_gui.py
if ($LASTEXITCODE -ne 0) { throw "changed Python contract syntax failed" }
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }
if (!(Test-Path -LiteralPath "out\winui\Release\flyExplorer.exe" -PathType Leaf)) { throw "previously validated Release artifact missing" }
python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 20500 --configuration Release --browse-over-complete-model
$guiExit=$LASTEXITCODE
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
if ($guiExit -ne 0) { throw "indexed filter layer diagnostic failed" }
Write-Host "LARGE_FOLDER_NAME_INDEX_FILTER_DIAGNOSTIC_PASS"
